  var Objects;
var NB;

  var cnv;

var wid;
var hei;

var NB_FRAMES;

var frame_count;

function activation(t) {
    return ((1-cos(2*PI*t))/2);
}

function object(id) {

    this.id = id;

    this.draw = function() {
        var t = ((frame_count)%NB_FRAMES)/NB_FRAMES;

        var x0 = lerp(0,wid,this.id/NB);

        theta = PI/2;

        var xx = x0;
        var yy = 0;

        var Nt = 25/2;

        var step = hei/Nt;

        var turn = lerp(0,0.7,activation((this.id/NB+0*t)%1));

        stroke(255);
        strokeWeight(1);
        fill(255);
        //beginShape();

        //vertex(xx,yy);


        for(var i=0;i<=Nt;i++){
            theta += turn*sin(100*noise(1000)+2*PI*(75*noise(0.2*this.id/NB,0.01*i)+t));
            //theta += turn*sin(100*noise(1000)+2*PI*(20*noise(0.02*i)+t + 0.1*sin(2*PI*this.id/NB)));
            xx += step*cos(theta);
            yy += step*sin(theta);

            var xx2 = lerp(xx,x0,(i/Nt)*(i/Nt)*(i/Nt));
            var yy2 = lerp(yy,lerp(0,hei-0,i/Nt),max((i/Nt),1-sqrt(i/Nt)));

            ellipse(xx2,yy2,1,1);


        }
        //endShape();

    }
}



